'use client';

import React from 'react';
import dynamic from 'next/dynamic';
import { useCarouselStore } from '@/store/carousel-store';
import { ArcTemplateSelector } from './ArcTemplateSelector';
import { SlideEditor } from './SlideEditor';
import { ThemedSlide } from '../preview/ThemedSlide';
import { PropertyPanel } from './PropertyPanel';
import { LayerPanel } from './LayerPanel';
import { Toolbar } from './Toolbar';
import { ZoomControls } from './ZoomControls';
import { PresetManager } from './PresetManager';
import { PREVIEW_SCALE, SLIDE_WIDTH, SLIDE_HEIGHT } from '@/config/constants';
import { Plus, GripVertical, Settings2, Layers } from 'lucide-react';

// Dynamically import CanvasSlide with SSR disabled to prevent canvas package requirement
const CanvasSlideEditor = dynamic(
  () => import('../preview/CanvasSlide').then(mod => ({ default: mod.CanvasSlideEditor })),
  { ssr: false }
);
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent,
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
  useSortable,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { Slide } from '@/types/index';
import { cn } from '@/lib/utils';

interface SortableSlideItemProps {
  slide: Slide;
  isSelected: boolean;
  onSelect: () => void;
  pillar: string;
  totalSlides: number;
  carouselBackgroundPack?: string;
}

function SortableSlideItem({ slide, isSelected, onSelect, pillar, totalSlides, carouselBackgroundPack }: SortableSlideItemProps) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: slide.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  // Calculate scale to fit within the sidebar width (w-80 = 320px, minus padding ≈ 280px)
  // Original slide is 1080px, so scale = 280 / 1080 ≈ 0.26
  const LIST_PREVIEW_SCALE = 0.26;

return (
    <div
      ref={setNodeRef}
      style={style}
      className={cn(
        'relative cursor-pointer rounded-lg overflow-hidden border-2 transition-all',
        isSelected ? 'border-white' : 'border-transparent hover:border-white/30'
      )}
      onClick={onSelect}
    >
      <div
        {...attributes}
        {...listeners}
        className="absolute top-2 left-2 z-10 p-1 bg-black/50 rounded cursor-grab active:cursor-grabbing"
      >
        <GripVertical className="w-4 h-4 text-white/70" />
      </div>
      <div className="absolute top-2 right-2 z-10 px-2 py-1 bg-black/50 rounded text-xs text-white/70">
        {slide.order + 1}
      </div>
      <div
        className="bg-gray-900 flex items-center justify-center"
        style={{
          width: SLIDE_WIDTH * LIST_PREVIEW_SCALE,
          height: SLIDE_HEIGHT * LIST_PREVIEW_SCALE,
        }}
      >
        <div
          style={{
            transform: `scale(${LIST_PREVIEW_SCALE})`,
            transformOrigin: 'center center',
          }}
        >
          <ThemedSlide
            slide={slide}
            pillar={pillar as any}
            isPreview
            carouselTotalSlides={totalSlides}
            carouselBackgroundPack={carouselBackgroundPack}
          />
        </div>
      </div>
    </div>
  );
}

export function CarouselEditor() {
  const {
    carousel,
    selectedSlideId,
    selectSlide,
    addSlide,
    reorderSlides,
  } = useCarouselStore();

  // Canvas mode state
  const [canvasMode, setCanvasMode] = React.useState(false);
  const [showPropertyPanel, setShowPropertyPanel] = React.useState(true);
  const [showLayerPanel, setShowLayerPanel] = React.useState(false);

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (over && active.id !== over.id) {
      reorderSlides(active.id as string, over.id as string);
    }
  };

  const handleAddSlide = () => {
    addSlide({
      type: 'content',
      content: {
        headline: 'New Slide',
        subtext: 'Edit this content...',
      },
    });
  };

  if (!carousel) {
    return (
      <div className="flex items-center justify-center h-full">
        <p className="text-white/60">No carousel loaded</p>
      </div>
    );
  }

  const selectedSlide = carousel.slides.find((s) => s.id === selectedSlideId);

  return (
    <div className="flex h-full gap-4">
      {/* Slide List Sidebar - Left Panel */}
      <div
        className="w-80 flex-shrink-0 bg-white/5 rounded-xl overflow-hidden flex flex-col"
        style={{ minHeight: 0 }}
      >
        <div className="p-4 border-b border-white/10 flex-shrink-0">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-medium text-white">Slides</h2>
            <span className="text-sm text-white/50">
              {carousel.slides.length}/10
            </span>
          </div>
        </div>
        <div className="flex-1 overflow-y-auto p-4" style={{ minHeight: 0 }}>
          <div className="space-y-4">

          <DndContext
            sensors={sensors}
            collisionDetection={closestCenter}
            onDragEnd={handleDragEnd}
          >
            <SortableContext
              items={carousel.slides.map((s) => s.id)}
              strategy={verticalListSortingStrategy}
            >
              <div className="space-y-2">
                {carousel.slides.map((slide) => (
                  <SortableSlideItem
                    key={slide.id}
                    slide={slide}
                    isSelected={slide.id === selectedSlideId}
                    onSelect={() => selectSlide(slide.id)}
                    pillar={carousel.pillar}
                    totalSlides={carousel.slides.length}
                    carouselBackgroundPack={carousel.carouselBackgroundPack}
                  />
                ))}
              </div>
            </SortableContext>
          </DndContext>

          {carousel.slides.length < 10 && (
            <button
              onClick={handleAddSlide}
              className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-white/5 hover:bg-white/10 rounded-lg text-white/70 hover:text-white transition-colors"
            >
              <Plus className="w-4 h-4" />
              Add Slide
            </button>
          )}
          </div>
        </div>
      </div>

      {/* Main Preview - Center Panel - FIXED, NO SCROLL */}
      <div className="flex-1 flex flex-col gap-4 overflow-hidden" style={{ minHeight: 0 }}>
        {/* Top Bar - Toolbar */}
        <div className="flex-shrink-0 flex items-center gap-4">
          {/* Canvas Mode Toggle */}
          <button
            onClick={() => setCanvasMode(!canvasMode)}
            className={cn(
              'flex items-center gap-2 px-4 py-2 rounded-lg transition-all',
              canvasMode
                ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30'
                : 'bg-white/5 text-white/70 hover:bg-white/10'
            )}
          >
            <Settings2 className="w-4 h-4" />
            <span className="text-sm font-medium">
              {canvasMode ? 'Canvas Mode' : 'DOM Mode'}
            </span>
          </button>

          {/* Toolbar (only in canvas mode) */}
          {canvasMode && (
            <Toolbar
              onFitToScreen={() => {
                // TODO: Implement fit to screen
              }}
              onToggleSnapGrid={() => {
                // TODO: Implement snap grid toggle
              }}
              snapGridEnabled={false}
            />
          )}
        </div>

        {/* Preview Area */}
        <div className="flex-1 flex items-center justify-center bg-white/5 rounded-xl overflow-hidden p-4" style={{ minHeight: 0 }}>
          {selectedSlide ? (
            <div
              style={{
                transform: `scale(${PREVIEW_SCALE})`,
                transformOrigin: 'center center',
              }}
            >
              {canvasMode ? (
                <CanvasSlideEditor
                  slide={selectedSlide}
                  pillar={carousel.pillar}
                  carouselTotalSlides={carousel?.slides.length}
                  carouselBackgroundPack={carousel?.carouselBackgroundPack}
                  carouselDecoratorConfig={carousel.decoratorConfig}
                  scale={1}
                />
              ) : (
                <ThemedSlide
                  slide={selectedSlide}
                  pillar={carousel.pillar}
                  carouselTotalSlides={carousel?.slides.length}
                  carouselBackgroundPack={carousel?.carouselBackgroundPack}
                />
              )}
            </div>
          ) : (
            <p className="text-white/60">Select a slide to preview</p>
          )}
        </div>
      </div>

      {/* Editor Sidebar - Right Panel */}
      <div
        className="w-96 flex-shrink-0 bg-white/5 rounded-xl overflow-hidden flex flex-col"
        style={{ minHeight: 0 }}
      >
        {/* Sidebar Header with Toggles */}
        <div className="p-4 border-b border-white/10 flex-shrink-0">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-medium text-white">Editor</h2>
            <div className="flex items-center gap-2">
              {/* Property Panel Toggle */}
              <button
                onClick={() => setShowPropertyPanel(!showPropertyPanel)}
                className={cn(
                  'p-2 rounded-lg transition-all',
                  showPropertyPanel
                    ? 'bg-cyan-500/20 text-cyan-400'
                    : 'bg-white/5 text-white/50 hover:bg-white/10'
                )}
                title="Toggle Property Panel"
              >
                <Settings2 className="w-4 h-4" />
              </button>

              {/* Layer Panel Toggle */}
              <button
                onClick={() => setShowLayerPanel(!showLayerPanel)}
                className={cn(
                  'p-2 rounded-lg transition-all',
                  showLayerPanel
                    ? 'bg-cyan-500/20 text-cyan-400'
                    : 'bg-white/5 text-white/50 hover:bg-white/10'
                )}
                title="Toggle Layer Panel"
              >
                <Layers className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto" style={{ minHeight: 0 }}>
          <div className="space-y-6 p-4">
            {/* Preset Manager */}
            <PresetManager />

            {/* Arc Template Selector */}
            <ArcTemplateSelector />

            {/* Layer Panel (canvas mode only) */}
            {canvasMode && showLayerPanel && (
              <div className="border-t border-white/10 pt-4">
                <LayerPanel />
              </div>
            )}

            {/* Property Panel (canvas mode only) */}
            {canvasMode && showPropertyPanel && (
              <div className="border-t border-white/10 pt-4">
                <PropertyPanel />
              </div>
            )}

            {/* Slide Editor (DOM mode only) */}
            {!canvasMode && selectedSlide && (
              <SlideEditor slide={selectedSlide} />
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
