'use client';

import React, { useState } from 'react';
import { styleTemplates, getStyleTemplate } from '@/config/styles';
import { StyleTemplateId } from '@/types/styles';

interface StyleTemplateSelectorProps {
  value: StyleTemplateId;
  onChange: (templateId: StyleTemplateId) => void;
  pillarColor?: string;
}

// Template categories
const TEMPLATE_CATEGORIES: Record<string, StyleTemplateId[]> = {
  'Modern': ['glassmorphism', 'cyberpunk', 'holographic', 'vaporwave'],
  'Minimal': ['minimal', 'swiss-minimal', 'gradient-mesh'],
  'Bold': ['brutalist', 'bold', 'geometric'],
  'Elegant': ['elegant', 'editorial', 'organic'],
  'Tech': ['isometric-3d', 'tech-data', 'modern'],
  'Creative': ['abstract-art', 'pattern', 'playful'],
};

export function StyleTemplateSelector({ value, onChange, pillarColor = '#00E5FF' }: StyleTemplateSelectorProps) {
  const [activeCategory, setActiveCategory] = useState('Modern');

  return (
    <div className="space-y-3">
      <label className="block text-sm font-medium text-gray-200">
        Style Template
      </label>

      {/* Category Tabs */}
      <div className="flex gap-2 overflow-x-auto pb-2">
        {Object.keys(TEMPLATE_CATEGORIES).map((category) => (
          <button
            key={category}
            onClick={() => setActiveCategory(category)}
            className={`px-3 py-1 rounded-full text-xs font-medium whitespace-nowrap transition-colors ${
              activeCategory === category
                ? 'bg-[var(--pillar-color)] text-black'
                : 'bg-gray-700 text-gray-400 hover:bg-gray-600'
            }`}
            style={{
              '--pillar-color': pillarColor,
            } as React.CSSProperties}
          >
            {category}
          </button>
        ))}
      </div>

      {/* Template Grid */}
      <div className="grid grid-cols-2 gap-2">
        {TEMPLATE_CATEGORIES[activeCategory].map((id) => {
          const template = styleTemplates[id];
          if (!template) return null;

          return (
            <button
              key={id}
              onClick={() => onChange(id as StyleTemplateId)}
              className={`
                relative p-3 rounded-lg border-2 transition-all text-left
                ${value === id
                  ? 'border-[var(--pillar-color)] bg-[var(--pillar-color)]10'
                  : 'border-gray-700 bg-gray-800/50 hover:border-gray-600'
                }
              `}
              style={{
                '--pillar-color': pillarColor,
              } as React.CSSProperties}
            >
              <div className="font-medium text-sm text-gray-100 capitalize">
                {id}
              </div>
              <div className="text-xs text-gray-400 mt-1">
                {template.layout.position}
              </div>
              {value === id && (
                <div
                  className="absolute top-2 right-2 w-2 h-2 rounded-full"
                  style={{ backgroundColor: pillarColor }}
                />
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
}