'use client';

import React, { useState } from 'react';
import { useCarouselStore } from '@/store/carousel-store';
import { Save, FolderOpen, Trash2, Edit2, Plus, X, Check } from 'lucide-react';
import { cn } from '@/lib/utils';

interface PresetManagerProps {
  className?: string;
}

export const PresetManager: React.FC<PresetManagerProps> = ({ className }) => {
  const { carousel, presets, savePreset, loadPreset, deletePreset, updatePreset } = useCarouselStore();
  const [isSaving, setIsSaving] = useState(false);
  const [isEditing, setIsEditing] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editDescription, setEditDescription] = useState('');
  const [newPresetName, setNewPresetName] = useState('');
  const [newPresetDescription, setNewPresetDescription] = useState('');

  const handleSavePreset = () => {
    if (!newPresetName.trim()) {
      alert('Please enter a preset name');
      return;
    }

    savePreset(newPresetName.trim(), newPresetDescription.trim() || undefined);
    setNewPresetName('');
    setNewPresetDescription('');
    setIsSaving(false);
  };

  const handleLoadPreset = (presetId: string) => {
    if (confirm('Loading a preset will replace your current carousel. Continue?')) {
      loadPreset(presetId);
    }
  };

  const handleDeletePreset = (presetId: string, presetName: string) => {
    if (confirm(`Are you sure you want to delete "${presetName}"?`)) {
      deletePreset(presetId);
    }
  };

  const handleStartEdit = (preset: any) => {
    setIsEditing(preset.id);
    setEditName(preset.name);
    setEditDescription(preset.description || '');
  };

  const handleSaveEdit = (presetId: string) => {
    if (!editName.trim()) {
      alert('Please enter a preset name');
      return;
    }

    updatePreset(presetId, editName.trim(), editDescription.trim() || undefined);
    setIsEditing(null);
    setEditName('');
    setEditDescription('');
  };

  const handleCancelEdit = () => {
    setIsEditing(null);
    setEditName('');
    setEditDescription('');
  };

  return (
    <div className={cn('space-y-4', className)}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold text-white">Presets</h3>
        <button
          onClick={() => setIsSaving(!isSaving)}
          disabled={!carousel}
          className={cn(
            'flex items-center gap-2 px-3 py-1.5 rounded-lg transition-all',
            carousel
              ? 'bg-cyan-500/20 text-cyan-400 hover:bg-cyan-500/30'
              : 'bg-white/5 text-white/30 cursor-not-allowed'
          )}
        >
          <Plus className="w-4 h-4" />
          <span className="text-sm">Save</span>
        </button>
      </div>

      {/* Save Preset Form */}
      {isSaving && (
        <div className="p-4 bg-white/5 rounded-lg space-y-3 animate-in fade-in slide-in-from-top-2">
          <div>
            <label className="block text-sm text-white/70 mb-1.5">Preset Name</label>
            <input
              type="text"
              value={newPresetName}
              onChange={(e) => setNewPresetName(e.target.value)}
              placeholder="Enter preset name..."
              className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white placeholder-white/30 focus:outline-none focus:border-cyan-400"
              autoFocus
            />
          </div>
          <div>
            <label className="block text-sm text-white/70 mb-1.5">Description (optional)</label>
            <textarea
              value={newPresetDescription}
              onChange={(e) => setNewPresetDescription(e.target.value)}
              placeholder="Add a description..."
              rows={2}
              className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white placeholder-white/30 focus:outline-none focus:border-cyan-400 resize-none"
            />
          </div>
          <div className="flex gap-2">
            <button
              onClick={handleSavePreset}
              className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-cyan-500/20 hover:bg-cyan-500/30 text-cyan-400 rounded-lg transition-all"
            >
              <Save className="w-4 h-4" />
              <span className="text-sm font-medium">Save Preset</span>
            </button>
            <button
              onClick={() => {
                setIsSaving(false);
                setNewPresetName('');
                setNewPresetDescription('');
              }}
              className="px-4 py-2 bg-white/5 hover:bg-white/10 text-white/70 rounded-lg transition-all"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      {/* Presets List */}
      <div className="space-y-2">
        {presets.length === 0 ? (
          <div className="py-8 px-4 text-center bg-white/5 rounded-lg">
            <FolderOpen className="w-12 h-12 mx-auto mb-3 text-white/30" />
            <p className="text-white/50 text-sm">No presets saved yet</p>
            <p className="text-white/30 text-xs mt-1">Save your carousel as a preset to reuse it later</p>
          </div>
        ) : (
          presets.map((preset) => (
            <div
              key={preset.id}
              className={cn(
                'group p-3 bg-white/5 hover:bg-white/10 rounded-lg transition-all',
                isEditing === preset.id && 'ring-2 ring-cyan-400 bg-white/10'
              )}
            >
              {isEditing === preset.id ? (
                // Edit Mode
                <div className="space-y-2">
                  <input
                    type="text"
                    value={editName}
                    onChange={(e) => setEditName(e.target.value)}
                    className="w-full px-2 py-1 bg-white/10 border border-white/20 rounded text-white text-sm focus:outline-none focus:border-cyan-400"
                  />
                  <textarea
                    value={editDescription}
                    onChange={(e) => setEditDescription(e.target.value)}
                    placeholder="Description..."
                    rows={2}
                    className="w-full px-2 py-1 bg-white/10 border border-white/20 rounded text-white text-sm focus:outline-none focus:border-cyan-400 resize-none"
                  />
                  <div className="flex gap-2">
                    <button
                      onClick={() => handleSaveEdit(preset.id)}
                      className="flex-1 flex items-center justify-center gap-1 px-3 py-1.5 bg-cyan-500/20 hover:bg-cyan-500/30 text-cyan-400 rounded text-sm transition-all"
                    >
                      <Check className="w-3.5 h-3.5" />
                      Save
                    </button>
                    <button
                      onClick={handleCancelEdit}
                      className="flex-1 flex items-center justify-center gap-1 px-3 py-1.5 bg-white/5 hover:bg-white/10 text-white/70 rounded text-sm transition-all"
                    >
                      <X className="w-3.5 h-3.5" />
                      Cancel
                    </button>
                  </div>
                </div>
              ) : (
                // View Mode
                <div className="flex items-start justify-between gap-2">
                  <div className="flex-1 min-w-0">
                    <h4 className="text-white font-medium text-sm truncate">{preset.name}</h4>
                    {preset.description && (
                      <p className="text-white/50 text-xs mt-0.5 line-clamp-2">{preset.description}</p>
                    )}
                    <div className="flex items-center gap-3 mt-2 text-xs text-white/40">
                      <span>{preset.carousel.slides.length} slides</span>
                      <span>•</span>
                      <span>{new Date(preset.updatedAt).toLocaleDateString()}</span>
                    </div>
                  </div>
                  <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button
                      onClick={() => handleLoadPreset(preset.id)}
                      className="p-1.5 hover:bg-white/10 rounded text-white/70 hover:text-white transition-all"
                      title="Load preset"
                    >
                      <FolderOpen className="w-3.5 h-3.5" />
                    </button>
                    <button
                      onClick={() => handleStartEdit(preset)}
                      className="p-1.5 hover:bg-white/10 rounded text-white/70 hover:text-white transition-all"
                      title="Edit preset"
                    >
                      <Edit2 className="w-3.5 h-3.5" />
                    </button>
                    <button
                      onClick={() => handleDeletePreset(preset.id, preset.name)}
                      className="p-1.5 hover:bg-red-500/20 rounded text-white/70 hover:text-red-400 transition-all"
                      title="Delete preset"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </div>
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
};