'use client';

import React from 'react';
import { ICON_REGISTRY } from '@/config/icons';

interface CTAButtonControlsProps {
  value: {
    text: string;
    style: 'solid' | 'outline' | 'gradient' | 'glowing' | 'minimal';
    shape: 'pill' | 'rounded' | 'square' | 'custom';
    icon?: string;
    iconPosition?: 'left' | 'right' | 'center';
    animation?: 'pulse' | 'glow' | 'bounce' | 'shake' | 'none';
  };
  onChange: (value: CTAButtonControlsProps['value']) => void;
  pillarColor?: string;
}

const BUTTON_STYLES = [
  { id: 'solid', label: 'Solid', description: 'Solid fill' },
  { id: 'outline', label: 'Outline', description: 'Border only' },
  { id: 'gradient', label: 'Gradient', description: 'Gradient fill' },
  { id: 'glowing', label: 'Glowing', description: 'With glow effect' },
  { id: 'minimal', label: 'Minimal', description: 'Simple style' },
] as const;

const BUTTON_SHAPES = [
  { id: 'pill', label: 'Pill', icon: '⬭' },
  { id: 'rounded', label: 'Rounded', icon: '▢' },
  { id: 'square', label: 'Square', icon: '⬜' },
  { id: 'custom', label: 'Custom', icon: '⚙' },
] as const;

const ANIMATIONS = [
  { id: 'none', label: 'None', description: 'No animation' },
  { id: 'pulse', label: 'Pulse', description: 'Pulsing effect' },
  { id: 'glow', label: 'Glow', description: 'Glowing effect' },
  { id: 'bounce', label: 'Bounce', description: 'Bouncing effect' },
  { id: 'shake', label: 'Shake', description: 'Shaking effect' },
] as const;

const ICON_POSITIONS = [
  { id: 'left', label: 'Left', icon: '⬅' },
  { id: 'center', label: 'Center', icon: '↔' },
  { id: 'right', label: 'Right', icon: '➡' },
] as const;

export function CTAButtonControls({
  value,
  onChange,
  pillarColor = '#00E5FF',
}: CTAButtonControlsProps) {
  const handleChange = (updates: Partial<CTAButtonControlsProps['value']>) => {
    onChange({
      ...value,
      ...updates,
    });
  };

  // Get available icons
  const availableIcons = Object.values(ICON_REGISTRY);

  return (
    <div className="space-y-4">
      {/* Button Text */}
      <div>
        <label className="block text-sm font-medium text-gray-200 mb-2">
          Button Text
        </label>
        <input
          type="text"
          value={value.text}
          onChange={(e) => handleChange({ text: e.target.value })}
          placeholder="Click Here"
          className="w-full px-3 py-2 bg-gray-800 border border-gray-700 rounded-lg text-sm text-gray-100 focus:border-[var(--pillar-color)] focus:outline-none"
          style={{
            '--pillar-color': pillarColor,
          } as React.CSSProperties}
        />
      </div>

      {/* Button Style */}
      <div>
        <label className="block text-sm font-medium text-gray-200 mb-2">
          Button Style
        </label>
        <div className="grid grid-cols-2 gap-2">
          {BUTTON_STYLES.map((style) => (
            <button
              key={style.id}
              onClick={() => handleChange({ style: style.id as any })}
              className={`
                p-3 rounded-lg border-2 transition-all text-left
                ${value.style === style.id
                  ? 'border-[var(--pillar-color)] bg-[var(--pillar-color)]10'
                  : 'border-gray-700 bg-gray-800/50 hover:border-gray-600'
                }
              `}
              style={{
                '--pillar-color': pillarColor,
              } as React.CSSProperties}
            >
              <div className="font-medium text-sm text-gray-100">
                {style.label}
              </div>
              <div className="text-xs text-gray-400 mt-1">
                {style.description}
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Button Shape */}
      <div>
        <label className="block text-sm font-medium text-gray-200 mb-2">
          Button Shape
        </label>
        <div className="grid grid-cols-4 gap-2">
          {BUTTON_SHAPES.map((shape) => (
            <button
              key={shape.id}
              onClick={() => handleChange({ shape: shape.id as any })}
              className={`
                p-2 rounded-lg border-2 transition-all text-center
                ${value.shape === shape.id
                  ? 'border-[var(--pillar-color)] bg-[var(--pillar-color)]10'
                  : 'border-gray-700 bg-gray-800/50 hover:border-gray-600'
                }
              `}
              style={{
                '--pillar-color': pillarColor,
              } as React.CSSProperties}
              title={shape.label}
            >
              <div className="text-2xl">{shape.icon}</div>
              <div className="text-xs text-gray-400 mt-1">
                {shape.label}
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Icon Selection */}
      <div>
        <label className="block text-sm font-medium text-gray-200 mb-2">
          Icon
        </label>
        <div className="flex gap-2 mb-2">
          <button
            onClick={() => handleChange({ icon: undefined })}
            className={`
              px-3 py-2 rounded-lg border-2 transition-all text-sm
              ${!value.icon
                ? 'border-[var(--pillar-color)] bg-[var(--pillar-color)]10'
                : 'border-gray-700 bg-gray-800/50 hover:border-gray-600'
              }
            `}
            style={{
              '--pillar-color': pillarColor,
            } as React.CSSProperties}
          >
            No Icon
          </button>
        </div>
        <div className="grid grid-cols-6 gap-2 max-h-48 overflow-y-auto">
          {availableIcons.map((icon) => (
            <button
              key={icon.name}
              onClick={() => handleChange({ icon: icon.name })}
              className={`
                p-2 rounded-lg border-2 transition-all text-center
                ${value.icon === icon.name
                  ? 'border-[var(--pillar-color)] bg-[var(--pillar-color)]10'
                  : 'border-gray-700 bg-gray-800/50 hover:border-gray-600'
                }
              `}
              style={{
                '--pillar-color': pillarColor,
              } as React.CSSProperties}
              title={icon.name}
            >
              <div className="text-xl">{icon.component()}</div>
            </button>
          ))}
        </div>
      </div>

      {/* Icon Position */}
      {value.icon && (
        <div>
          <label className="block text-sm font-medium text-gray-200 mb-2">
            Icon Position
          </label>
          <div className="grid grid-cols-3 gap-2">
            {ICON_POSITIONS.map((pos) => (
              <button
                key={pos.id}
                onClick={() => handleChange({ iconPosition: pos.id as any })}
                className={`
                  p-2 rounded-lg border-2 transition-all text-center
                  ${value.iconPosition === pos.id
                    ? 'border-[var(--pillar-color)] bg-[var(--pillar-color)]10'
                    : 'border-gray-700 bg-gray-800/50 hover:border-gray-600'
                  }
                `}
                style={{
                  '--pillar-color': pillarColor,
                } as React.CSSProperties}
              >
                <div className="text-lg">{pos.icon}</div>
                <div className="text-xs text-gray-400 mt-1">
                  {pos.label}
                </div>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Animation */}
      <div>
        <label className="block text-sm font-medium text-gray-200 mb-2">
          Animation
        </label>
        <div className="grid grid-cols-2 gap-2">
          {ANIMATIONS.map((anim) => (
            <button
              key={anim.id}
              onClick={() => handleChange({ animation: anim.id as any })}
              className={`
                p-3 rounded-lg border-2 transition-all text-left
                ${value.animation === anim.id
                  ? 'border-[var(--pillar-color)] bg-[var(--pillar-color)]10'
                  : 'border-gray-700 bg-gray-800/50 hover:border-gray-600'
                }
              `}
              style={{
                '--pillar-color': pillarColor,
              } as React.CSSProperties}
            >
              <div className="font-medium text-sm text-gray-100">
                {anim.label}
              </div>
              <div className="text-xs text-gray-400 mt-1">
                {anim.description}
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Preview */}
      <div className="pt-4 border-t border-gray-700">
        <label className="block text-xs text-gray-400 mb-2">Preview</label>
        <div className="p-4 bg-gray-900 rounded-lg flex items-center justify-center">
          <div
            className={`
              px-6 py-3 rounded-lg font-medium text-sm flex items-center gap-2
              ${value.style === 'solid' && 'bg-[var(--pillar-color)] text-black'}
              ${value.style === 'outline' && 'border-2 border-[var(--pillar-color)] text-[var(--pillar-color)]'}
              ${value.style === 'gradient' && 'bg-gradient-to-r from-[var(--pillar-color)] to-transparent text-black'}
              ${value.style === 'glowing' && 'bg-[var(--pillar-color)] text-black shadow-[0_0_20px_var(--pillar-color)]'}
              ${value.style === 'minimal' && 'bg-transparent text-[var(--pillar-color)] border border-gray-600'}
              ${value.shape === 'pill' && 'rounded-full'}
              ${value.shape === 'rounded' && 'rounded-lg'}
              ${value.shape === 'square' && 'rounded-none'}
              ${value.animation === 'pulse' && 'animate-pulse'}
              ${value.animation === 'glow' && 'shadow-lg'}
              ${value.animation === 'bounce' && 'animate-bounce'}
              ${value.animation === 'shake' && 'animate-shake'}
            `}
            style={{
              '--pillar-color': pillarColor,
            } as React.CSSProperties}
          >
            {value.iconPosition === 'left' && value.icon && (
              <span>{availableIcons.find(i => i.name === value.icon)?.component()}</span>
            )}
            <span>{value.text || 'Click Here'}</span>
            {value.iconPosition === 'right' && value.icon && (
              <span>{availableIcons.find(i => i.name === value.icon)?.component()}</span>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}