/**
 * Sub-Type Selector Component
 *
 * Allows users to select a sub-type preset for the current slide.
 * Displays available sub-types with descriptions and optional thumbnails.
 *
 * @module components/editor/SubTypeSelector
 */

'use client';

import React from 'react';
import { ChevronDown } from 'lucide-react';
import { getSubTypesForSlideType, getDefaultSubType, type SlideSubType } from '@/config/slide-subtypes';
import type { SlideType } from '@/types/slide';

interface SubTypeSelectorProps {
  slideType: SlideType;
  currentSubType?: string;
  onChange: (subTypeId: string) => void;
  pillarColor?: string;
  className?: string;
}

interface SubTypeOption {
  subType: SlideSubType;
  isDefault: boolean;
}

/**
 * Sub-Type Selector Component
 *
 * Provides a dropdown to select from available sub-types for the current slide type.
 * Shows description and default indicator for each sub-type.
 */
export const SubTypeSelector: React.FC<SubTypeSelectorProps> = ({
  slideType,
  currentSubType,
  onChange,
  pillarColor,
  className = '',
}) => {
  const [isOpen, setIsOpen] = React.useState(false);

  // Get available sub-types for this slide type
  const subTypes = getSubTypesForSlideType(slideType);
  const defaultSubType = getDefaultSubType(slideType);

  // Get current sub-type object
  const currentSubTypeObj = subTypes.find((st) => st.id === currentSubType);

  // Handle sub-type change
  const handleChange = (subTypeId: string) => {
    onChange(subTypeId);
    setIsOpen(false);
  };

  return (
    <div className={`relative ${className}`}>
      <label className="block text-sm font-medium text-white/70 mb-2">
        Layout Preset
      </label>

      {/* Dropdown Button */}
      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white text-left flex items-center justify-between hover:bg-white/15 focus:outline-none focus:border-white/40 transition-colors"
      >
        <div className="flex items-center gap-2">
          {currentSubTypeObj && (
            <span className="text-xs px-2 py-0.5 rounded bg-white/10">
              {currentSubTypeObj.name}
            </span>
          )}
          {currentSubTypeObj?.isDefault && (
            <span className="text-xs text-purple-400">(default)</span>
          )}
        </div>
        <ChevronDown className={`w-4 h-4 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
      </button>

      {/* Dropdown Menu */}
      {isOpen && (
        <>
          {/* Backdrop */}
          <div
            className="fixed inset-0 z-40"
            onClick={() => setIsOpen(false)}
          />

          {/* Menu */}
          <div className="absolute z-50 w-full mt-1 bg-gray-900 border border-white/20 rounded-lg shadow-xl max-h-64 overflow-y-auto">
            {subTypes.map((subType) => {
              const isSelected = subType.id === currentSubType;
              const isDefault = subType.id === defaultSubType?.id;

              return (
                <button
                  key={subType.id}
                  type="button"
                  onClick={() => handleChange(subType.id)}
                  className={`w-full px-3 py-2 text-left hover:bg-white/10 transition-colors border-b border-white/5 last:border-0 ${
                    isSelected ? 'bg-white/20' : ''
                  }`}
                >
                  <div className="flex items-center justify-between">
                    <div className="flex flex-col">
                      <div className="flex items-center gap-2">
                        <span className="text-sm font-medium text-white">
                          {subType.name}
                        </span>
                        {isDefault && (
                          <span className="text-xs px-2 py-0.5 rounded bg-purple-500/20 text-purple-400">
                            Default
                          </span>
                        )}
                      </div>
                      <span className="text-xs text-white/60 mt-1">
                        {subType.description}
                      </span>
                    </div>
                    {isSelected && (
                      <span className="w-2 h-2 rounded-full bg-green-500" />
                    )}
                  </div>
                </button>
              );
            })}

            {subTypes.length === 0 && (
              <div className="px-3 py-4 text-center text-white/50 text-sm">
                No presets available for this slide type
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
};

export default SubTypeSelector;