import React, { useState, useCallback } from 'react';
import { useCanvasStore } from '@/store/canvas-store';
import { CanvasElement } from '@/types/canvas-elements';
import { cn } from '@/lib/utils';

/**
 * LayerPanel component props
 */
interface LayerPanelProps {
  className?: string;
}

/**
 * LayerPanel - Manage element layers, visibility, and locking
 *
 * Features:
 * - List all elements sorted by z-index
 * - Layer selection (click)
 * - Show/hide layers (toggle)
 * - Lock/unlock layers (toggle)
 * - Layer reordering (drag and drop)
 * - Delete layer (delete key)
 */
export const LayerPanel: React.FC<LayerPanelProps> = ({ className }) => {
  const { elements, selectedIds, selectElement, deselectAll, updateElement, deleteElement } = useCanvasStore();

  /**
   * Get sorted elements by z-index
   */
  const sortedElements = React.useMemo(() => {
    return Array.from(elements.values()).sort((a, b) => b.zIndex - a.zIndex);
  }, [elements]);

  /**
   * Handle layer selection
   */
  const handleLayerClick = useCallback((elementId: string, event: React.MouseEvent) => {
    event.stopPropagation();
    selectElement(elementId, event.shiftKey);
  }, [selectElement]);

  /**
   * Handle visibility toggle
   */
  const handleVisibilityToggle = useCallback((elementId: string, event: React.MouseEvent) => {
    event.stopPropagation();
    const element = elements.get(elementId);
    if (element) {
      updateElement(elementId, { visible: !element.visible });
    }
  }, [elements, updateElement]);

  /**
   * Handle lock toggle
   */
  const handleLockToggle = useCallback((elementId: string, event: React.MouseEvent) => {
    event.stopPropagation();
    const element = elements.get(elementId);
    if (element) {
      updateElement(elementId, { locked: !element.locked });
    }
  }, [elements, updateElement]);

  /**
   * Handle layer move up
   */
  const handleMoveUp = useCallback((elementId: string, event: React.MouseEvent) => {
    event.stopPropagation();
    const element = elements.get(elementId);
    if (!element) return;

    const elementsAbove = sortedElements.filter(e => e.zIndex > element.zIndex);
    if (elementsAbove.length > 0) {
      const nextElement = elementsAbove[elementsAbove.length - 1];
      updateElement(elementId, { zIndex: nextElement.zIndex });
      updateElement(nextElement.id, { zIndex: element.zIndex });
    }
  }, [elements, sortedElements, updateElement]);

  /**
   * Handle layer move down
   */
  const handleMoveDown = useCallback((elementId: string, event: React.MouseEvent) => {
    event.stopPropagation();
    const element = elements.get(elementId);
    if (!element) return;

    const elementsBelow = sortedElements.filter(e => e.zIndex < element.zIndex);
    if (elementsBelow.length > 0) {
      const nextElement = elementsBelow[elementsBelow.length - 1];
      updateElement(elementId, { zIndex: nextElement.zIndex });
      updateElement(nextElement.id, { zIndex: element.zIndex });
    }
  }, [elements, sortedElements, updateElement]);

  /**
   * Handle layer bring to front
   */
  const handleBringToFront = useCallback((elementId: string, event: React.MouseEvent) => {
    event.stopPropagation();
    const element = elements.get(elementId);
    if (!element) return;

    const maxZIndex = Math.max(...Array.from(elements.values()).map(e => e.zIndex));
    updateElement(elementId, { zIndex: maxZIndex + 1 });
  }, [elements, updateElement]);

  /**
   * Handle layer send to back
   */
  const handleSendToBack = useCallback((elementId: string, event: React.MouseEvent) => {
    event.stopPropagation();
    const element = elements.get(elementId);
    if (!element) return;

    const minZIndex = Math.min(...Array.from(elements.values()).map(e => e.zIndex));
    updateElement(elementId, { zIndex: Math.max(0, minZIndex - 1) });
  }, [elements, updateElement]);

  /**
   * Handle layer delete
   */
  const handleDelete = useCallback((elementId: string, event: React.MouseEvent) => {
    event.stopPropagation();
    deleteElement(elementId);
  }, [deleteElement]);

  /**
   * Get element icon based on type
   */
  const getElementIcon = (type: string) => {
    switch (type) {
      case 'text':
        return (
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" />
          </svg>
        );
      case 'image':
        return (
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
          </svg>
        );
      case 'background':
        return (
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21a4 4 0 01-4-4V5a2 2 0 012-2h4a2 2 0 012 2v12a4 4 0 01-4 4zm0 0h12a2 2 0 002-2v-4a2 2 0 00-2-2h-2.343M11 7.343l1.657-1.657a2 2 0 012.828 0l2.829 2.829a2 2 0 010 2.828l-8.486 8.485M7 17h.01" />
          </svg>
        );
      case 'cta':
        return (
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 15l-2 5L9 9l11 4-5 2zm0 0l5 5M7.188 2.239l.777 2.897M5.136 7.965l-2.898-.777M13.95 4.05l-2.122 2.122m-5.657 5.656l-2.12 2.122" />
          </svg>
        );
      case 'decorator':
        return (
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" />
          </svg>
        );
      case 'shape':
        return (
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 5a1 1 0 011-1h14a1 1 0 011 1v14a1 1 0 01-1 1H5a1 1 0 01-1-1V5z" />
          </svg>
        );
      default:
        return (
          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 10h16M4 14h16M4 18h16" />
          </svg>
        );
    }
  };

  return (
    <div className={cn(
      'bg-black/20 backdrop-blur-xl border border-white/10 rounded-2xl p-6',
      'h-full flex flex-col',
      className
    )}>
      {/* Header */}
      <div className="mb-4 pb-4 border-b border-white/10">
        <h3 className="text-white font-semibold text-lg">Layers</h3>
        <p className="text-white/50 text-sm">
          {sortedElements.length} {sortedElements.length === 1 ? 'layer' : 'layers'}
        </p>
      </div>

      {/* Layer List */}
      <div className="flex-1 overflow-y-auto space-y-1">
        {sortedElements.length === 0 ? (
          <div className="flex items-center justify-center h-full">
            <p className="text-white/50 text-sm">No layers yet</p>
          </div>
        ) : (
          sortedElements.map((element) => (
            <LayerItem
              key={element.id}
              element={element}
              isSelected={selectedIds.includes(element.id)}
              onClick={handleLayerClick}
              onVisibilityToggle={handleVisibilityToggle}
              onLockToggle={handleLockToggle}
              onMoveUp={handleMoveUp}
              onMoveDown={handleMoveDown}
              onBringToFront={handleBringToFront}
              onSendToBack={handleSendToBack}
              onDelete={handleDelete}
              icon={getElementIcon(element.type)}
            />
          ))
        )}
      </div>
    </div>
  );
};

/**
 * Layer item component
 */
interface LayerItemProps {
  element: CanvasElement;
  isSelected: boolean;
  onClick: (elementId: string, event: React.MouseEvent) => void;
  onVisibilityToggle: (elementId: string, event: React.MouseEvent) => void;
  onLockToggle: (elementId: string, event: React.MouseEvent) => void;
  onMoveUp: (elementId: string, event: React.MouseEvent) => void;
  onMoveDown: (elementId: string, event: React.MouseEvent) => void;
  onBringToFront: (elementId: string, event: React.MouseEvent) => void;
  onSendToBack: (elementId: string, event: React.MouseEvent) => void;
  onDelete: (elementId: string, event: React.MouseEvent) => void;
  icon: React.ReactNode;
}

const LayerItem: React.FC<LayerItemProps> = ({
  element,
  isSelected,
  onClick,
  onVisibilityToggle,
  onLockToggle,
  onMoveUp,
  onMoveDown,
  onBringToFront,
  onSendToBack,
  onDelete,
  icon,
}) => {
  const [isHovered, setIsHovered] = useState(false);

  return (
    <div
      className={cn(
        'group relative flex items-center gap-2 px-3 py-2 rounded-lg transition-all',
        'hover:bg-white/5',
        isSelected ? 'bg-white/10 border border-white/20' : 'border border-transparent'
      )}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {/* Drag Handle */}
      <div className="cursor-grab text-white/30 hover:text-white/50">
        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8h16M4 16h16" />
        </svg>
      </div>

      {/* Element Icon */}
      <div className="text-white/50">
        {icon}
      </div>

      {/* Element Name */}
      <div
        className="flex-1 text-sm text-white/70 truncate cursor-pointer select-none"
        onClick={(e) => onClick(element.id, e)}
      >
        {element.name}
      </div>

      {/* Visibility Toggle */}
      <button
        onClick={(e) => onVisibilityToggle(element.id, e)}
        className={cn(
          'p-1 rounded transition-colors',
          element.visible
            ? 'text-white/50 hover:text-white'
            : 'text-white/20 hover:text-white/50'
        )}
        title={element.visible ? 'Hide' : 'Show'}
      >
        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          {element.visible ? (
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
          ) : (
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.59 3.59m0 0A9.953 9.953 0 0112 5c4.478 0 8.268 2.943 9.543 7a10.025 10.025 0 01-4.132 5.411m0 0L21 21" />
          )}
        </svg>
      </button>

      {/* Lock Toggle */}
      <button
        onClick={(e) => onLockToggle(element.id, e)}
        className={cn(
          'p-1 rounded transition-colors',
          element.locked
            ? 'text-yellow-400/70 hover:text-yellow-400'
            : 'text-white/30 hover:text-white/50'
        )}
        title={element.locked ? 'Unlock' : 'Lock'}
      >
        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          {element.locked ? (
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
          ) : (
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 11V7a4 4 0 118 0m-4 8v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
          )}
        </svg>
      </button>

      {/* Layer Controls (shown on hover) */}
      {isHovered && (
        <div className="flex items-center gap-1">
          {/* Send to Back */}
          <button
            onClick={(e) => onSendToBack(element.id, e)}
            className="p-1 rounded text-white/30 hover:text-white hover:bg-white/10 transition-colors"
            title="Send to Back"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 14l-7 7m0 0l-7-7m7 7V3" />
            </svg>
          </button>

          {/* Move Down */}
          <button
            onClick={(e) => onMoveDown(element.id, e)}
            className="p-1 rounded text-white/30 hover:text-white hover:bg-white/10 transition-colors"
            title="Move Down"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          </button>

          {/* Move Up */}
          <button
            onClick={(e) => onMoveUp(element.id, e)}
            className="p-1 rounded text-white/30 hover:text-white hover:bg-white/10 transition-colors"
            title="Move Up"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" />
            </svg>
          </button>

          {/* Bring to Front */}
          <button
            onClick={(e) => onBringToFront(element.id, e)}
            className="p-1 rounded text-white/30 hover:text-white hover:bg-white/10 transition-colors"
            title="Bring to Front"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" />
            </svg>
          </button>

          {/* Delete */}
          <button
            onClick={(e) => onDelete(element.id, e)}
            className="p-1 rounded text-white/30 hover:text-red-400 hover:bg-red-500/10 transition-colors"
            title="Delete Layer"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
            </svg>
          </button>
        </div>
      )}
    </div>
  );
};